from common import *
def md(f,decimals=6):
    f=f.copy()
    for k in f.select_dtypes('number'):
        f[k]=f[k].map(lambda x:f'{x:.{decimals}f}' if isinstance(x,(float,np.floating)) else str(x))
    lines=['| '+' | '.join(f.columns)+' |','| '+' | '.join(['---']*len(f.columns))+' |']
    lines+=['| '+' | '.join(map(str,r))+' |' for r in f.itertuples(index=False,name=None)]
    return '\n'.join(lines)+'\n'
